package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonHold {
    public void record(@Val Person person, @Val ChangedBy by, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId() + " by="
                + by.name() + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

/** A validated hold change: whether the person is to be held. */
public record HoldInput(boolean held) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Whether to hold or release the person. Publishes it, with the user making the change. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> hold, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.held() == null) {
            throw new BadRequestException("Say whether to hold or release the person");
        }
        hold.set(new HoldInput(request.held()));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

/** Whether to put the person on hold (true) or take them off it (false), and the signed-in user (`by`) doing it. */
public record HoldRequest(Boolean held, String by) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold or takes them off it; refuses when they are in that state already. */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Person person, PersonRepository repository)
            throws BadRequestException {
        if (person.isHeld() == input.held() || !repository.hold(person.getId(), input.held())) {
            throw new BadRequestException(input.held() ? "That person is already on hold; reload the sheet"
                    : "That person is not on hold; reload the sheet");
        }
        person.setHeld(input.held());
    }
}
