content.content:
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures, as the screen shows them: a person's claimed is their counting claims' amounts added up;
 * their due-total is those claims' figures added up (a claim's figure: its settled due, else the figure a statement
 * bound it to, else its amount times the rate in force on its date of the grade in force on its date, rounded half up when the claim rounds by a date before the sheet's policy date, else half to even, and at least the sheet's floor;
 * none without a rate) with its late charge added on top while it is overdue, n/a when their grade on the sheet's today has no rate then and no counting claim keeps a settled or bound
 * figure or one at another grade. After a change, records one ROLLUP line per person whose figures it moved, then a TOTALS line when the
 * sheet's totals moved. A held person's OPEN and PENDING claims count in none of these; their SETTLED claims still do.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, Audit audit) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    public RollupSnapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.list(sheetId);
        List<Claim> sheetClaims = claims.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        for (Person p : people.list(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            boolean kept = false;
            for (Claim c : sheetClaims) {
                if (c.getPersonId() != p.getId() || !counts(c, p.isHeld())) {
                    continue;
                }
                claimed = claimed.add(c.getAmount().setScale(2));
                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
                String grade = p.gradeOn(c.getDate());
                BigDecimal figure = late.due(c, figure(c, grade, sheetRates, floor, late));
                // A figure at a grade other than today's does not hang on today's grade having a rate.
                kept |= figure != null && !grade.equals(p.getGrade());
                if (figure != null) {
                    due = due.add(figure);
                }
            }
            BigDecimal personDue = kept || rateOn(sheetRates, p.getGrade(), today) != null ? due : null;
            figures.put(p.getId(), new Figures(p.getName(), claimed, personDue));
            claimedTotal = claimedTotal.add(claimed);
            if (personDue != null) {
                dueTotal = dueTotal.add(personDue);
            }
        }
        return new RollupSnapshot(figures, claimedTotal, dueTotal);
    }

    /**
     * The due-total of the counting claims dated from..to (inclusive), as the screen shows a period's: each claim's
     * figure (with its late charge) added up, a claim without one adding nothing.
     */
    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.list(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
        Map<Long, Person> byId = new LinkedHashMap<>();
        for (Person p : people.list(sheetId)) {
            byId.put(p.getId(), p);
        }
        BigDecimal total = ZERO;
        for (Claim c : claims.list(sheetId)) {
            Person p = byId.get(c.getPersonId());
            if (p == null || !counts(c, p.isHeld()) || c.getDate().isBefore(from) || c.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal figure = late.due(c, figure(c, p.gradeOn(c.getDate()), sheetRates, floor, late));
            if (figure != null) {
                total = total.add(figure);
            }
        }
        return total;
    }

    /** The claim's due as the screen shows it now: its figure with its late charge on top; null (n/a) without one. */
    public BigDecimal dueOf(Claim claim) {
        String sheetId = claim.getSheetId();
        Person p = people.find(sheetId, claim.getPersonId());
        if (p == null) {
            return null;
        }
        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
        return late.due(claim, figure(claim, p.gradeOn(claim.getDate()), rates.list(sheetId), settings.floor(sheetId), late));
    }

    /** Record the figures the change moved, from {@code before} to the sheet's figures now. */
    public void record(String sheetId, RollupSnapshot before, ChangedBy by) {
        RollupSnapshot after = snapshot(sheetId);
        List<String> lines = new ArrayList<>();
        String who = " sheet=" + sheetId + " by=" + by.name();
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.movedFrom(before.people().get(e.getKey()))) {
                lines.add("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
                        + " due-total=" + show(now.dueTotal()));
            }
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())) {
            lines.add("TOTALS" + who + " claimed-total=" + after.claimedTotal().toPlainString() + " due-total="
                    + after.dueTotal().toPlainString());
        }
        lines.forEach(audit::record);
    }

    /** Whether the claim counts in the live totals: a held person's OPEN and PENDING claims do not; their SETTLED ones do. */
    private static boolean counts(Claim claim, boolean held) {
        return claim.getStatus().counts() && !(held && claim.getStatus().isOpen());
    }

    private static String show(BigDecimal figure) {
        return figure == null ? "n/a" : figure.toPlainString();
    }

    /** A claim's figure; a live one (neither settled nor bound) is at least the sheet's floor, unless it is a correction. */
    private static BigDecimal figure(Claim claim, String grade, List<Rate> sheetRates, BigDecimal floor, LateCharge late) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue().setScale(2);
        }
        if (claim.isBound()) {
            return claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2);
        }
        BigDecimal rate = rateOn(sheetRates, grade, claim.getDate());
        return claim.figureAt(rate, floor, late.rounding(claim));
    }

    /** The grade's rate in force on the date: the latest from-date on or before it, none counting as the earliest. */
    private static BigDecimal rateOn(List<Rate> sheetRates, String grade, LocalDate on) {
        Rate found = null;
        for (Rate r : sheetRates) {
            if (!r.grade().equals(grade) || (r.from() != null && r.from().isAfter(on))) {
                continue;
            }
            if (found == null || (r.from() != null && (found.from() == null || r.from().isAfter(found.from())))) {
                found = r;
            }
        }
        return found == null ? null : found.rate();
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statements;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
 * figure its last statement bound it to, else its amount times the rate in force on the claim's date of its
 * person's grade in force on that date (rounded as the claim rounds by the sheet's policy date, and at least the sheet's floor; none without a rate). The due-total is the counting claims' figures
 * added up, each with its late charge on top while it is overdue (the charge is never bound); n/a
 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        List<Claim> mine = claims.listOf(sheetId, person.getId());
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim c : mine) {
            // A held person's OPEN and PENDING claims do not count; their SETTLED ones still do.
            if (!c.getStatus().counts() || (person.isHeld() && c.getStatus().isOpen())) {
                claims.bind(c.getId(), false, null);
                continue;
            }
            counted++;
            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
            BigDecimal figure = figure(c, person, rates, floor, late);
            // A figure at a grade other than today's does not hang on today's grade having a rate.
            kept |= figure != null && !person.gradeOn(c.getDate()).equals(person.getGrade());
            if (figure != null) {
                sum = sum.add(late.due(c, figure));
            }
            claims.bind(c.getId(), true, figure);
        }
        BigDecimal dueTotal = kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null;
        statements.insert(sheetId, person.getId(), dueTotal, today);
        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
        taken.set(new Statement(dueTotal, counted));
    }

    private static BigDecimal figure(Claim claim, Person person, RateRepository rates, BigDecimal floor, LateCharge late) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        BigDecimal rate = rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        return claim.figureAt(rate, floor, late.rounding(claim));
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people on each sheet; ids are assigned in the order people are added. */
@Repository
public class PersonRepository {

    /** A person's columns, with the grade in force on the sheet's today, their statement count and their last statement's due-total and date. */
    private static final String COLUMNS = "p.id, p.sheet_id, p.name, p.version, p.retired_from, p.held,"
            + " (SELECT g.grade FROM person_grade g WHERE g.person_id = p.id AND (g.from_date IS NULL"
            + " OR g.from_date <= (SELECT t.today FROM sheet t WHERE t.id = p.sheet_id))"
            + " ORDER BY g.from_date DESC NULLS LAST LIMIT 1) AS grade,"
            + " (SELECT COUNT(*) FROM statement s WHERE s.person_id = p.id) AS statement_count,"
            + " (SELECT s.due_total FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS stated_total,"
            + " (SELECT s.taken_on FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS statement_date";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getString("grade"), rs.getLong("version"));
        person.setStatements(new Statements(rs.getInt("statement_count"), rs.getBigDecimal("stated_total"),
                rs.getObject("statement_date", LocalDate.class)));
        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
        person.setHeld(rs.getBoolean("held"));
        return person;
    };

    private static final RowMapper<GradeFrom> GRADE = (rs, n) -> new GradeFrom(rs.getString("grade"),
            rs.getObject("from_date", LocalDate.class));

    static final String CHANGED = "Someone else has saved this person since you opened it; the form now shows their changes";

    static final String NAME_TAKEN = "That name is already in use on this sheet";

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in the order they were added. */
    public List<Person> list(String sheetId) {
        return withPatrons(sheetId,
                jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? ORDER BY p.id", ROW, sheetId));
    }

    public Person find(String sheetId, long id) {
        return withPatrons(sheetId,
                jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND p.id = ?", ROW, sheetId, id))
                .stream().findFirst().orElse(null);
    }

    /** The person on the sheet with this name, ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        return withPatrons(sheetId, jdbc.query(
                "SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND p.name_key = LOWER(TRIM(?))", ROW, sheetId,
                name)).stream().findFirst().orElse(null);
    }

    /** Whether another person on the sheet has this name, ignoring case and surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    /** Add the person, their grade in force from the beginning of time. */
    public Person insert(String sheetId, String name, String grade) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name) VALUES (?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            return ps;
        }, keys);
        long id = keys.getKey().longValue();
        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, NULL)", id, grade);
        Person person = new Person(id, sheetId, name, grade, 0);
        person.setGrades(List.of(new GradeFrom(grade, null)));
        return person;
    }

    /** Give the person the grade from the date, replacing one given from that same date and keeping the rest;
     *  the person's grades are then re-read, and their grade set to the one in force on {@code today}. */
    public void giveGrade(Person person, String grade, LocalDate from, LocalDate today) {
        jdbc.update("DELETE FROM person_grade WHERE person_id = ? AND from_date = ?", person.getId(),
                java.sql.Date.valueOf(from));
        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, ?)", person.getId(), grade,
                java.sql.Date.valueOf(from));
        person.setGrades(jdbc.query("SELECT grade, from_date FROM person_grade WHERE person_id = ?", GRADE,
                person.getId()));
        person.setGrade(person.gradeOn(today));
    }

    /** Saves the person if it is still at the version it was loaded at, moving it to the next
     *  version; false (nothing written) when someone else saved it in the meantime. */
    public boolean update(Person person) {
        int n = jdbc.update("UPDATE person SET name = ?, version = version + 1 WHERE id = ? AND version = ?",
                person.getName(), person.getId(), person.getVersion());
        if (n == 0) {
            return false;
        }
        person.setVersion(person.getVersion() + 1);
        return true;
    }

    /** Retire the person from the date; false (nothing written) when they were retired already. */
    public boolean retire(long id, LocalDate from) {
        return jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND retired_from IS NULL",
                java.sql.Date.valueOf(from), id) == 1;
    }

    /** Put the person on hold, or take them off it; false (nothing written) when they were in that state already. */
    public boolean hold(long id, boolean held) {
        return jdbc.update("UPDATE person SET held = ? WHERE id = ? AND held = ?", held, id, !held) == 1;
    }

    /** Name the patron as the person's patron; false (nothing written) when they are one already. */
    public boolean addPatron(long personId, long patronId) {
        try {
            return jdbc.update("INSERT INTO person_patron (person_id, patron_id) SELECT ?, ? WHERE NOT EXISTS"
                    + " (SELECT 1 FROM person_patron WHERE person_id = ? AND patron_id = ?)",
                    personId, patronId, personId, patronId) == 1;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** Sets each person's patrons' names, sorted, and their grades. */
    private List<Person> withPatrons(String sheetId, List<Person> people) {
        if (people.isEmpty()) {
            return people;
        }
        Map<Long, List<GradeFrom>> grades = jdbc.query(
                "SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person q ON q.id = g.person_id"
                        + " WHERE q.sheet_id = ?",
                (rs, n) -> Map.entry(rs.getLong("person_id"), GRADE.mapRow(rs, n)), sheetId).stream()
                .collect(Collectors.groupingBy(Map.Entry::getKey,
                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
        for (Person person : people) {
            person.setGrades(grades.getOrDefault(person.getId(), List.of()));
        }
        Map<Long, List<String>> patrons = jdbc.query(
                "SELECT pp.person_id, q.name FROM person_patron pp JOIN person q ON q.id = pp.patron_id"
                        + " WHERE q.sheet_id = ?",
                (rs, n) -> Map.entry(rs.getLong("person_id"), rs.getString("name")), sheetId).stream()
                .collect(Collectors.groupingBy(Map.Entry::getKey,
                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
        for (Person person : people) {
            person.setPatrons(patrons.getOrDefault(person.getId(), List.of()).stream().sorted().toList());
        }
        return people;
    }
}
